.footer-column h4 {
    font-size: 20px;
    margin-bottom: 25px;
    position: relative;
}

.footer-column h4::after {
    content: "";
    width: 50px;
    height: 3px;
    background: #cc2326;
    position: absolute;
    left: 0;
