}

.footer-column p {
    color: #cfcfcf;
    line-height: 1.8;
    margin-bottom: 25px;
}

.footer-column ul {
    list-style: none;
}

.footer-column ul li {
    margin-bottom: 14px;
}

.footer-column ul li a {
    color: #cfcfcf;
    text-decoration: none;
    transition: 0.3s;
}

.footer-column ul li a:hover {
    color: #cc2326;
    padding-left: 5px;
}

.contact-list li {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    color: #cfcfcf;
}

.contact-list i {
    color: #cc2326;
    margin-top: 4px;
}

.social-links {
    display: flex;
    gap: 15px;
}

.social-links a {
    width: 42px;
    height: 42px;
    background: rgba(255,255,255,0.1);
    color: #fff;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-decoration: none;
    transition: 0.3s;
}

.social-links a:hover {
    background: #cc2326;
    transform: translateY(-5px);
}

.footer-bottom {
    border-top: 1px solid rgba(255,255,255,0.1);
    margin-top: 60px;
    padding-top: 20px;
    text-align: center;
}

.footer-bottom p {
    color: #aaa;
    font-size: 14px;
}

