    font-family: var(--font-primary);
}

html {
    scroll-behavior: smooth;
}

body {
    background: var(--dark-bg);
    color: var(--white);
    line-height: 1.7;
    overflow-x: hidden;
}

/* Container */
.container {
    width: var(--container-width);
    max-width: var(--container-max-width);
    margin: 0 auto;
